WITH months AS (SELECT DISTINCT month_first_day FROM {{ ref('valid_orders_month') }}), month_ends AS (SELECT month_first_day, CAST(month_first_day AS DATE) + INTERVAL '1 month' - INTERVAL '1 day' AS month_end FROM months), eligible AS (SELECT c.member_id, me.month_first_day FROM {{ ref('cards') }} c CROSS JOIN month_ends me WHERE c.card_type IN ('悦享年卡', '家庭季卡') AND c.valid_from <= me.month_end AND c.valid_until > me.month_end AND (c.ended_at IS NULL OR c.ended_at > me.month_end)), base AS (SELECT v.member_month_key, v.member_id, v.month_first_day, v.valid_order_cnt, v.valid_net_cents FROM {{ ref('valid_orders_month') }} v), joined AS (SELECT b.member_month_key, b.member_id, b.month_first_day, b.valid_order_cnt, b.valid_net_cents, CASE WHEN e.member_id IS NOT NULL THEN TRUE ELSE FALSE END AS is_paid_member FROM base b LEFT JOIN eligible e ON e.member_id = b.member_id AND e.month_first_day = b.month_first_day) SELECT member_month_key, member_id, month_first_day, valid_order_cnt, valid_net_cents, is_paid_member FROM joined